// Phân tích intent từ tin nhắn Telegram
const msg = $input.first().json.message;
const chatId = msg.chat.id;
const text = (msg.text || '').toLowerCase().trim();
const username = msg.from?.first_name || 'Khách';

// Danh sách intent patterns
const intents = {
  greeting: /^(chào|hi|hello|hey|chao|xin chào|hí|hì|alo|bot|ngọc)/i,
  order: /^(đặt|mua|order|muốn mua|đặt hàng|thanh toán|mua ngay|cho mình đặt|đặt mua)/i,
  price: /(giá|bao nhiêu|bảng giá|price|cost|tiền|khoảng|tầm giá|tổng)/i,
  delivery: /(giao hàng|ship|giao|nhận hàng|bao lâu|giao tận nơi|phí giao|thời gian giao)/i,
  info: /(địa chỉ|liên hệ|hotline|số điện thoại|zalo|facebook|giờ mở|làm việc|ở đâu)/i,
  care: /(chăm sóc|bảo quản|giữ tươi|cách cắm|cắt cành|thay nước|tưới)/i,
  meaning: /(ý nghĩa|thông điệp|tượng trưng|biểu tượng|có nghĩa|tặng gì|dịp nào)/i,
  reset: /^(reset|xóa lịch sử|làm mới)/i,
};

// Xác định intent chính
let detectedIntent = 'general';
for (const [intent, pattern] of Object.entries(intents)) {
  if (pattern.test(text)) {
    detectedIntent = intent;
    break;
  }
}

console.log(`[${chatId}] ${username}: "${text}" -> intent: ${detectedIntent}`);

return [{
  json: {
    chatId: chatId,
    text: msg.text,
    username: username,
    intent: detectedIntent,
    messageId: msg.message_id,
    date: msg.date,
    chatType: msg.chat.type,
    firstName: msg.from?.first_name || '',
    lastName: msg.from?.last_name || '',
    usernameFrom: msg.from?.username || '',
    isGroup: msg.chat.type !== 'private',
  }
}];

// Lấy lịch sử chat từ workflow static data
const chatId = $input.first().json.chatId;
const historyKey = `tg_history_${chatId}`;
const chatHistory = $getWorkflowStaticData('global')[historyKey] || [];

return [{
  json: {
    ...$input.first().json,
    chatHistory: chatHistory
  }
}];

