}];

// Xử lý phản hồi từ Ollama và cập nhật lịch sử
const data = $input.first().json;
const chatId = data.chatId;

// Lấy nội dung reply
const replyContent = data.message?.content 
  || data?.json?.message?.content 
  || 'Xin lỗi, mình chưa hiểu. Bạn nói lại giúp mình nhé! 🌸';

// Cập nhật lịch sử
const historyKey = `tg_history_${chatId}`;
let history = $getWorkflowStaticData('global')[historyKey] || [];
history.push({ role: "assistant", content: replyContent });
if (history.length > 20) {
  history = history.slice(-20);
}
$getWorkflowStaticData('global')[historyKey] = history;

return [{ json: { chatId: chatId, text: replyContent } }];

// Lưu lịch sử chat và chuẩn bị gửi reply
const data = $input.first().json;
const chatId = data.chatId;

// Lưu lịch sử cho các handler không phải AI
const historyKey = `tg_history_${chatId}`;
let history = $getWorkflowStaticData('global')[historyKey] || [];
// Tránh lưu duplicate nếu AI đã lưu rồi
const lastEntry = history[history.length - 1];
if (!lastEntry || lastEntry.content !== data.text) {
  history.push({ role: "assistant", content: data.text });
  if (history.length > 20) history = history.slice(-20);
  $getWorkflowStaticData('global')[historyKey] = history;
}

return [{ json: { chatId: chatId, text: data.text } }];

